import 'server-only'
import type { Evaluation, Terms, Turn } from '@/lib/negotiation/types'
import { getDb } from '../db'
import { initialState, step, type PlayerAction } from '../engine/engine'
import { evaluateGame } from '../engine/evaluate'
import type { ScenarioContext } from '../engine/utility'

/**
 * Public showcase content generated by the real engine (not hand-written):
 *  - previewMove: one Classic-mode move from the opening of a scenario
 *  - sampleReport: a scripted practice run scored by the evaluation engine
 * Both are labelled as demonstrations in the UI.
 */

async function ctxFor(slug: string): Promise<ScenarioContext | null> {
  const db = await getDb()
  const doc = await db.scenarios.findOne({ slug, visibility: 'PUBLIC', published: true })
  if (!doc) return null
  const ver = await db.scenarioVersions.findOne({ scenarioId: doc._id, version: doc.currentVersion })
  return ver ? { pub: ver.public, priv: ver.private } : null
}

export const PREVIEW_SLUG = 'buy-used-car'
export const PREVIEW_MOVES = {
  why: { label: 'Ask why he is selling', action: { type: 'ASK', questionKey: 'why-selling' } },
  anchor: { label: 'Offer $8,600 straight away', action: { type: 'MAKE_OFFER', terms: { price: 8600 } } },
  best: { label: 'Ask for his best price', action: { type: 'ASK', questionKey: 'proposal' } },
} as const satisfies Record<string, { label: string; action: PlayerAction }>

export async function previewMove(move: keyof typeof PREVIEW_MOVES) {
  const ctx = await ctxFor(PREVIEW_SLUG)
  if (!ctx) return null
  const res = step(ctx, initialState(ctx), PREVIEW_MOVES[move].action as PlayerAction)
  const counter = res.state.counterOffer?.price ?? null
  const gapRange = ctx.pub.issues[0]!.max - ctx.pub.issues[0]!.min
  const own = res.state.playerOffer?.price ?? ctx.pub.brief.suggestedTargets.price!
  return {
    turns: res.turns.map((t) => ({ actor: t.actor, text: t.text, revealed: t.revealed ?? [], note: t.note ?? null })),
    gap: counter ? Math.min(1, Math.abs(counter - own) / (gapRange * 0.6)) : 0.85,
    rapport: res.state.trust - ctx.priv.counterpart.trustStart,
  }
}

let cached: { at: number; data: { evaluation: Evaluation; title: string; turns: number; terms: Terms | null } } | null = null

export async function sampleReport() {
  if (cached && Date.now() - cached.at < 10 * 60 * 1000) return cached.data
  const ctx = await ctxFor(PREVIEW_SLUG)
  if (!ctx) return null
  const script: PlayerAction[] = [
    { type: 'ASK', questionKey: 'drive' },
    { type: 'ASK', questionKey: 'inspect' },
    { type: 'ASK', questionKey: 'why-selling' },
    { type: 'STATEMENT', statementKey: 'tyres' },
    { type: 'MAKE_OFFER', terms: { price: 8600 } },
    { type: 'MAKE_OFFER', terms: { price: 8900 } },
    { type: 'ACCEPT' },
  ]
  let state = initialState(ctx)
  const turns: Turn[] = []
  let outcome: { kind: 'AGREEMENT' | 'NO_DEAL'; terms: Terms | null } = { kind: 'NO_DEAL', terms: null }
  for (const a of script) {
    const r = step(ctx, state, a)
    r.turns.forEach((t) => turns.push({ ...t, idx: turns.length, at: '' }))
    state = r.state
    if (r.status !== 'ACTIVE') {
      outcome = r.outcome as typeof outcome
      break
    }
  }
  const evaluation = evaluateGame({ ctx, state, turns, prep: { targets: { price: 8600 }, walkAway: { price: 10200 }, plan: 'Inspect first, find out why he is selling, then anchor with evidence.' }, outcome })
  const data = { evaluation, title: ctx.pub.title, turns: state.turn, terms: outcome.terms }
  cached = { at: Date.now(), data }
  return data
}
